#!/usr/bin/env python3
from pwn import *
from collections import defaultdict, Counter
from time import time

def verify_number(base, num):
    # Implement the same check as the server
    dic = defaultdict(int)
    for i in range(base):
        dic[base-i-1] = num % base
        num = num // base
    count = Counter(dic.values())
    count = defaultdict(int, count)
    return all(dic[i] == count[i] for i in dic.items()) and num == 0

def find_self_descriptive(base):
    print(f"Finding self-descriptive number for base {base}")
    start_time = time()

    # Initialize array with zeros
    # We know: total sum of digits must equal base
    # Most digits will be 0s
    digits = [0] * base

    def is_valid_partial(pos, curr_sum):
        if curr_sum > base:
            return False
        if pos >= 10 and curr_sum < base:
            # Check if remaining positions can be filled with zeros
            zeros_needed = base - curr_sum
            return zeros_needed >= 0 and (digits[0] == 0 or digits[0] == zeros_needed)
        return True

    def solve_recursive(pos=1, curr_sum=0):
        if not is_valid_partial(pos, curr_sum):
            return False

        if pos == 10:
            # Fill position 0 with count of zeros
            zeros_needed = base - curr_sum
            digits[0] = zeros_needed

            # Convert to decimal and verify
            result = sum(d * (base ** i) for i, d in enumerate(digits))
            return verify_number(base, result)

        # Try values for current position
        max_val = min(base - curr_sum, base - 1)  # Cannot exceed base-1 as a digit
        for val in range(max_val + 1):
            digits[pos] = val
            if solve_recursive(pos + 1, curr_sum + val):
                return True
        digits[pos] = 0
        return False

    if solve_recursive():
        result = sum(d * (base ** i) for i, d in enumerate(digits))
        print(f"Found solution in {time() - start_time:.2f} seconds")
        return result

    print(f"No solution found after {time() - start_time:.2f} seconds")
    return None

def solve_challenge():
    context.log_level = 'debug'
    HOST = 'crypto.chal.csaw.io'
    PORT = 21200

    try:
        conn = remote(HOST, PORT)
        print("Connected to server")

        while True:
            try:
                data = conn.recvuntil(b'>').decode()
                print("Received:", data)

                if 'csawctf{' in data:
                    print("Found flag!")
                    return data

                if 'base' not in data:
                    print("No base found in response")
                    break

                base = int(data.split('base')[1].split()[0])
                print(f"Extracted base: {base}")

                answer = find_self_descriptive(base)
                if answer is not None:
                    print(f"Sending answer: {answer}")
                    conn.sendline(str(answer).encode())
                else:
                    print("No solution found")
                    break

            except EOFError:
                print("Server closed connection")
                break

    except Exception as e:
        print(f"Error occurred: {e}")
    finally:
        try:
            conn.close()
        except:
            pass

if __name__ == "__main__":
    print("Starting challenge solution...")
    result = solve_challenge()
    if result:
        print("Final result:", result)

